s=s.replace("(r.reason==='manual'?'手动留图':'候选自动留图')","(r.reason==='manual'?'手动留图':r.selection==='FPGA_PRODUCT_BEST_FRAME'?'FPGA 最佳证据帧':'历史报警留图')")
